style.css:
@-moz-document domain("scpfoundation.net"), domain("scpfoundation.ru"), domain("scp-ru.wikidot.com") {
/* BASE
     Articles ship their own <style> after this sheet, so equal specificity
     loses: article-body rules carry !important, and the ones a theme is
     likeliest to claim use two ids so an author's inline colour still wins. */

  /* Headings and links state colour directly — inheritance cannot recolour them, so a light author box rebinds these tokens for its subtree instead. */
  :root {
    color-scheme: dark;
    --scpru-title: #e05f6b;
    --scpru-heading: #e6edf3;
    --scpru-link: #e8626e;
    --scpru-link-visited: #cf90a8;
    --scpru-link-hover: #ff8f97;
    --scpru-newpage: #e8944a;
    --scpru-lift-black: #c4cdd6;
    --scpru-lift-blue: #79c0ff;
    --scpru-lift-green: #7ee787;
    --scpru-lift-purple: #d2a8ff;
    --scpru-lift-maroon: #ff9492;
    --scpru-lift-red: #ff453a;
    --scpru-lift-brown: #d4a373;
    --scpru-lift-teal: #56d4dd;

    /* Feeds the 2023 sidebar's corner brackets, folded-section wipe and section rules. */
    --new-side-bar-color: #8a2f2f;

    /* Basalt-family surfaces, bare `r,g,b` triplets fed to rgb(). The palette
       moves whole: fill the surfaces one at a time and the ink pitched against
       them is stranded. `light-text` sits ON the family's accent chips and stays
       light; `sub-text` and the accent hues are left alone. !important because
       the themes state these on :root after this sheet. */
    --basalt-primary-color: 20, 24, 29 !important;
    --basalt-secondary-color: 26, 31, 38 !important;
    --basalt-tertiary-color: 45, 51, 59 !important;
    --basalt-main-text-color: 230, 237, 243 !important;
    --basalt-light-text-color: 230, 237, 243 !important;
    --header-background-color: 26, 31, 38 !important;
    --header-border-color: 45, 51, 59 !important;

    /* Cosmonaut's light-panel colour, reached by a `z-index: -1` pseudo that paints over any background-color on the box — the token is the only handle. */
    --hazyCyanColor: #1a1f26 !important;

    /* Black Highlighter's link ink, resolved on :root for the footnote numerals,
       the pager and the contents box — a rebind lower down cannot reach those. */
    --link-color: 232, 98, 110 !important;
  }

  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* A visual theme that names the id outranks the element selector above. */
  html body#html-body {
    background-color: #14181d !important;
  }

  #html-body,
  #skrollr-body,
  #container-wrap-wrap,
  #container,
  #action-area {
    background-color: transparent;
  }

  /* ACTION AREA — the click-gated panels the page-options rail
     swaps in: rating, history, page source, backlinks, authorship
     Nothing here is authored, so this is the one place the heading
     colour is pinned. */
  #action-area h1 {
    color: var(--scpru-title) !important;
  }

  #action-area h2,
  #action-area h3,
  #action-area h4,
  #action-area h5,
  #action-area h6 {
    color: var(--scpru-heading) !important;
  }

  /* Outside the article column: the two-id link rule below never reaches it, and a theme's bare `a` wins on document order. */
  #action-area .printuser a,
  #action-area .printuser a:visited {
    color: var(--scpru-link) !important;
  }

  /* Panel-scoped only — `text-general` also inks the wiki content table, which the themes that paint it near-white need dark. */
  #action-area,
  #who-rated-page-area {
    --swatch-text-general: 230, 237, 243 !important;
    --swatch-secondary-color: 28, 33, 40 !important;
  }

  /* Token resolved on :root, out of reach of the block above; the skin's own selector ties this specificity from a later sheet. */
  #action-area .pager {
    color: #e6edf3 !important;
  }

  /* Forced clear: a theme painting these near-white strands the page's ink on paper it was never measured against. */
  #content-wrap,
  #main-content,
  #page-content,
  #login-status,
  #login-status span,
  #page-options-container {
    background-color: transparent !important;
  }

  /* Only the 140-165px top-menu stripe is opaque in the artwork, so a first
     background layer repaints it and the artwork stays as the second. The URL
     must stay absolute — userstyles.org rejects relative url() at upload. */
  div#container-wrap {
    background-color: #14181d !important;
    background-image:
      linear-gradient(transparent 140px, #1c2128 140px, #1c2128 165px, transparent 165px),
      url("https://scpfoundation.net/-/static/images/scp-bg.png") !important;
    background-repeat: repeat-x, repeat-x !important;
    background-position: top left, top left !important;
  }

  /* iframe default border is 2px inset currentColor — turns light with the text. */
  iframe {
    border-color: #2d333b;
  }

  hr {
    color: #2d333b !important;
    background-color: #2d333b !important;
    border-color: #2d333b !important;
  }

  /* `.hr-logos` keeps its own teal bar and only loses the `#ccc` halo. */
  .hr-main,
  .hr-big,
  .hr-logos {
    box-shadow: 0 2px 3px rgba(0, 0, 0, .5) !important;
  }

  .hr-main,
  .hr-big {
    background-color: #3a4048 !important;
  }

  /* TYPOGRAPHY */

  /* Page floor always, so pinned. `.page-title` is the class form an article draws when it hides `#page-title`. */
  #page-title,
  .meta-title,
  .sub-page-title,
  .sub-page-title h1,
  #page-content .page-title {
    color: var(--scpru-title) !important;
    border-color: #2d333b !important;
  }

  /* Id form only — the class form is author markup and may carry paper of its own. */
  #page-title {
    background-color: transparent !important;
  }

  /* Not pinned: an article stating a heading colour has its own surface in mind, and document order already beats the site's base #901. */
  h1 {
    color: var(--scpru-title);
    border-color: #2d333b;
  }

  h2,
  h3,
  h4,
  h5,
  h6 {
    color: var(--scpru-heading);
  }

  /* Sigma-9 gives h2–h6 no colour of their own, so inside a box that states
     `color:` inline they take the box's ink natively; the element rule above
     would state one directly and beat that inheritance. h1 is excluded: the
     site colours it directly, so it never inherited. Anchored on the
     declaration boundary — a `-color:` longhand (`background-color:`,
     `--link-color:`) can never precede `color:` with `^`, `;` or `; `. */
  #page-content [style^="color:"] h2,
  #page-content [style*=";color:"] h2,
  #page-content [style*="; color:"] h2,
  #page-content [style^="color:"] h3,
  #page-content [style*=";color:"] h3,
  #page-content [style*="; color:"] h3,
  #page-content [style^="color:"] h4,
  #page-content [style*=";color:"] h4,
  #page-content [style*="; color:"] h4,
  #page-content [style^="color:"] h5,
  #page-content [style*=";color:"] h5,
  #page-content [style*="; color:"] h5,
  #page-content [style^="color:"] h6,
  #page-content [style*=";color:"] h6,
  #page-content [style*="; color:"] h6 {
    color: inherit !important;
  }

  /* Article root ONLY — on p/li/dd/dt/td it would be a direct declaration beating an author's callout-box colour, erasing their ink under their light paper. */
  #page-content,
  .thread-container .post .content,
  .forum-thread-box .description-block {
    color: #c4cdd6;
  }

  /* Authors build callout boxes as [[div style="background:#EEE"]] with no ink
     of their own, so the paper survives the theme and the box must hand the ink
     back. Matched on the VALUE, never on a class: classes are page-local.
     EVERY form names the background PROPERTY immediately before its value —
     matching a light hex anywhere in the attribute reads the author's INK as
     their paper and puts near-black ink on a dark plate. The cost: a light
     colour appearing only as a GRADIENT STOP no longer matches.
     The KEYWORDS listed last are only those whose luminance carries near-black
     ink better than light ink; `blue`, `navy`, `purple` and `maroon` are absent
     for the reverse reason, `darkred` and relatives excluded by the
     property-adjacent form alone.
     NOT !important, so an author who named their own colour still wins. */
  #page-content [style*="background:#c"],
  #page-content [style*="background: #c"],
  #page-content [style*="background-color:#c"],
  #page-content [style*="background-color: #c"],
  #page-content [style*="background:#d"],
  #page-content [style*="background: #d"],
  #page-content [style*="background-color:#d"],
  #page-content [style*="background-color: #d"],
  #page-content [style*="background:#e"],
  #page-content [style*="background: #e"],
  #page-content [style*="background-color:#e"],
  #page-content [style*="background-color: #e"],
  #page-content [style*="background:#f"],
  #page-content [style*="background: #f"],
  #page-content [style*="background-color:#f"],
  #page-content [style*="background-color: #f"],
  #page-content [style*="background:#C"],
  #page-content [style*="background: #C"],
  #page-content [style*="background-color:#C"],
  #page-content [style*="background-color: #C"],
  #page-content [style*="background:#D"],
  #page-content [style*="background: #D"],
  #page-content [style*="background-color:#D"],
  #page-content [style*="background-color: #D"],
  #page-content [style*="background:#E"],
  #page-content [style*="background: #E"],
  #page-content [style*="background-color:#E"],
  #page-content [style*="background-color: #E"],
  #page-content [style*="background:#F"],
  #page-content [style*="background: #F"],
  #page-content [style*="background-color:#F"],
  #page-content [style*="background-color: #F"],
  /* Below the `#c` floor the group above starts at, and the only such value on the branch. */
  #page-content [style*="background:#bfe1ff"],
  #page-content [style*="background: #bfe1ff"],
  #page-content [style*="background :#bfe1ff"],
  #page-content [style*="background : #bfe1ff"],
  #page-content [style*="background-color:#bfe1ff"],
  #page-content [style*="background-color: #bfe1ff"],
  #page-content [style*="background:#BFE1FF"],
  #page-content [style*="background: #BFE1FF"],
  #page-content [style*="background-color:#BFE1FF"],
  #page-content [style*="background-color: #BFE1FF"],
  #page-content [style*="background:white"],
  #page-content [style*="background: white"],
  #page-content [style*="background-color:white"],
  #page-content [style*="background-color: white"],
  #page-content [style*="background:red"],
  #page-content [style*="background: red"],
  #page-content [style*="background-color:red"],
  #page-content [style*="background-color: red"],
  #page-content [style*="background:yellow"],
  #page-content [style*="background: yellow"],
  #page-content [style*="background-color:yellow"],
  #page-content [style*="background-color: yellow"],
  #page-content [style*="background:orange"],
  #page-content [style*="background: orange"],
  #page-content [style*="background-color:orange"],
  #page-content [style*="background-color: orange"],
  #page-content [style*="background:gold"],
  #page-content [style*="background: gold"],
  #page-content [style*="background-color:gold"],
  #page-content [style*="background-color: gold"],
  #page-content [style*="background:lime"],
  #page-content [style*="background: lime"],
  #page-content [style*="background-color:lime"],
  #page-content [style*="background-color: lime"],
  #page-content [style*="background:aqua"],
  #page-content [style*="background: aqua"],
  #page-content [style*="background-color:aqua"],
  #page-content [style*="background-color: aqua"],
  #page-content [style*="background:cyan"],
  #page-content [style*="background: cyan"],
  #page-content [style*="background-color:cyan"],
  #page-content [style*="background-color: cyan"],
  #page-content [style*="background:pink"],
  #page-content [style*="background: pink"],
  #page-content [style*="background-color:pink"],
  #page-content [style*="background-color: pink"],
  #page-content [style*="background:magenta"],
  #page-content [style*="background: magenta"],
  #page-content [style*="background-color:magenta"],
  /* Wikidot keeps author spacing verbatim: `background :#F5F5F5` is a separate spelling. The space occurs only before the colon, only on the shorthand. */
  #page-content [style*="background :#c"],
  #page-content [style*="background : #c"],
  #page-content [style*="background :#d"],
  #page-content [style*="background : #d"],
  #page-content [style*="background :#e"],
  #page-content [style*="background : #e"],
  #page-content [style*="background :#f"],
  #page-content [style*="background : #f"],
  #page-content [style*="background :#C"],
  #page-content [style*="background : #C"],
  #page-content [style*="background :#D"],
  #page-content [style*="background : #D"],
  #page-content [style*="background :#E"],
  #page-content [style*="background : #E"],
  #page-content [style*="background :#F"],
  #page-content [style*="background : #F"],
  #page-content [style*="background :white"],
  #page-content [style*="background : white"],
  #page-content [style*="background :red"],
  #page-content [style*="background : red"],
  #page-content [style*="background :yellow"],
  #page-content [style*="background : yellow"],
  #page-content [style*="background :orange"],
  #page-content [style*="background : orange"],
  #page-content [style*="background :gold"],
  #page-content [style*="background : gold"],
  #page-content [style*="background :lime"],
  #page-content [style*="background : lime"],
  #page-content [style*="background :aqua"],
  #page-content [style*="background : aqua"],
  #page-content [style*="background :cyan"],
  #page-content [style*="background : cyan"],
  #page-content [style*="background :pink"],
  #page-content [style*="background : pink"],
  #page-content [style*="background :magenta"],
  #page-content [style*="background : magenta"],
  #page-content [style*="background-color: magenta"] {
    color: #140f0c;
    --scpru-title: #7a1d24;
    --scpru-heading: #140f0c;
    --scpru-link: #a4161a;
    --scpru-link-visited: #6d3550;
    --scpru-link-hover: #d21414;
    --scpru-newpage: #8a4b00;
    /* On light paper the author's own dark end of the ##blue|…## palette reads, and the lifted end does not. */
    --scpru-lift-black: #140f0c;
    --scpru-lift-blue: #0000cd;
    --scpru-lift-green: #046307;
    --scpru-lift-purple: #800080;
    --scpru-lift-maroon: #800000;
    --scpru-lift-red: #c30000;
    --scpru-lift-brown: #6b4423;
    --scpru-lift-teal: #006a6a;
  }

  /* The rebind above travels into nested boxes through the custom properties,
     which the box's own `color` cannot stop, so every surface we force dark
     restores the dark-page token set. The guard mirrors each fill rule's. */
  #page-content .code:not([style*="background"]),
  #page-content #toc:not([style*="background"]),
  #page-content .page-source:not([style*="background"]),
  #page-content div.note:not([style*="background"]),
  #page-content div.note-block:not([style*="background"]),
  #page-content blockquote:not([style*="background"]),
  #page-content div.blockquote:not([style*="background"]),
  #page-content .content-panel:not([style*="background"]),
  #page-content .content-panel.standalone[style*="#FFF"],
  #page-content .content-panel.standalone[style*="#fff"],
  #page-content .content-panel.standalone[style*="white"],
  #page-content .content-panel.standalone[style*="#ececec"],
  #page-content .content-panel.standalone[style*="#ECECEC"],
  #page-content .content-panel.standalone[style*="#f5f5f5"],
  #page-content .content-panel.standalone[style*="#F5F5F5"],
  #page-content .content-panel.standalone[style*="#fcfdfb"],
  #page-content .content-panel.standalone[style*="#FCFDFB"],
  #page-content .collapsible-block,
  #page-content .footnotes-footer,
  #page-content .fncon,
  #page-content div.wiki-note,
  #page-content .hovertip,
  #page-content div.sexy-box,
  #page-content .scp-image-block .scp-image-caption,
  #page-content .scp-front-block,
  #page-content .banner-block {
    color: #c4cdd6;
    --scpru-title: #e05f6b;
    --scpru-heading: #e6edf3;
    --scpru-link: #e8626e;
    --scpru-link-visited: #cf90a8;
    --scpru-link-hover: #ff8f97;
    --scpru-newpage: #e8944a;
    --scpru-lift-black: #c4cdd6;
    --scpru-lift-blue: #79c0ff;
    --scpru-lift-green: #7ee787;
    --scpru-lift-purple: #d2a8ff;
    --scpru-lift-maroon: #ff9492;
    --scpru-lift-red: #ff453a;
    --scpru-lift-brown: #d4a373;
    --scpru-lift-teal: #56d4dd;
  }

  /* LINKS — the crimson identity, lifted for dark */

  a,
  #interwiki a,
  #side-bar a,
  #side-bar a:visited,
  #page-content a {
    color: var(--scpru-link);
  }

  a:visited,
  #page-content a:visited {
    color: var(--scpru-link-visited);
  }

  a:hover,
  #page-content a:hover {
    color: var(--scpru-link-hover);
  }

  /* Themes reach body links from page-scoped rules out-specifying one id. Two ids win on id count, so no !important — an inline colour and the ##name|text## lifts below still win. */
  #main-content #page-content a {
    color: var(--scpru-link);
  }

  #main-content #page-content a:visited {
    color: var(--scpru-link-visited);
  }

  #main-content #page-content a:hover {
    color: var(--scpru-link-hover);
  }

  /* Site chrome outside the article column: a skin's bare `a` wins on document order against the one-id rule above. */
  #main-content #breadcrumbs a,
  #main-content #breadcrumbs a:visited {
    color: var(--scpru-link);
  }

  #main-content #breadcrumbs a:hover {
    color: var(--scpru-link-hover);
  }

  /* Low specificity, so component rules (the rating buttons) can still fill their own hover. */
  a:hover {
    background-color: transparent !important;
  }

  a.newpage,
  a.newpage:visited,
  #main-content #page-content a.newpage,
  #main-content #page-content a.newpage:visited {
    color: var(--scpru-newpage);
  }

  #page-content a.collapsible-block-link {
    color: var(--scpru-link);
  }

  /* MASTHEAD / TOP BAR / SEARCH */

  #header h1 a {
    color: #eee;
  }

  #header h2 span {
    color: #f0f0c0;
  }

  /* Themes hide the real text with `color: transparent` and draw a pseudo copy;
     colouring the anchor would print a second title over it. `color` only — a
     knocked-out-artwork title sets -webkit-text-fill-color transparent. */
  #header h1 a::before,
  #header h1 a::after {
    color: #eee !important;
  }

  #header h2::before,
  #header h2::after,
  #header h2 span::before,
  #header h2 span::after {
    color: #f0f0c0 !important;
  }

  #login-status {
    color: #9aa4ae !important;
  }

  #login-status a,
  #login-status a.btn,
  #login-status a.btn-primary {
    background-color: transparent !important;
    border-color: transparent !important;
    color: #dde3e9 !important;
  }

  #login-status a:hover {
    color: #ff8f97 !important;
  }

  #login-status ul a,
  #account-options li a {
    color: #e8626e !important;
  }

  #account-options {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, .6);
  }

  #account-options li a:hover {
    color: #ff8f97 !important;
    background-color: #262c33 !important;
  }

  #account-topbutton {
    background-color: #2d333b !important;
    color: #e8626e !important;
    border-color: #3a4048 !important;
  }

  /* A theme's near-black `#top-bar a` comes from the page's <style> after this sheet, so equal weight loses. No theme names the fill property. */
  #top-bar a {
    color: #eaeaea !important;
    -webkit-text-fill-color: #eaeaea !important;
  }

  /* The anchor fills below cover only the rows, not the gaps between them. */
  #top-bar ul li ul {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    box-shadow: 0 4px 12px rgba(0, 0, 0, .7);
  }

  /* All four sides stated so the zero-width two stay off currentColor.
     The row carries its own plate: the band beneath is often ancestor artwork,
     everything between computes `rgba(0,0,0,0)`, and a contrast walk then reads
     a base nowhere near the pixels. The plate is the site's own top-menu
     stripe, seamless where a theme leaves the band alone. */
  #top-bar ul li a {
    background-color: #1c2128 !important;
    border-color: rgba(255, 255, 255, .06) !important;
  }

  /* Restated: the bar's own fill declaration otherwise reaches every row inside it. */
  #top-bar ul li.sfhover a,
  #top-bar ul li:hover a,
  #top-bar li ul li a,
  #top-bar a:hover {
    background-color: #1c2128 !important;
    color: #ff8f97 !important;
    -webkit-text-fill-color: #ff8f97 !important;
    border-left-color: #3a4048 !important;
    border-right-color: #3a4048 !important;
  }

  #top-bar ul li.sfhover a:hover,
  #top-bar ul li:hover a:hover {
    background-color: #262c33 !important;
  }

  #top-bar ul li.sfhover ul li a,
  #top-bar ul li:hover ul li a {
    border-top-color: #2d333b !important;
  }

  #top-bar ul li ul a {
    color: #ff8f97;
  }

  /* Mobile hamburger — a white disc with a grey rule and a grey glyph. Two ids:
     Black Highlighter clears the disc from a page <style> at more than one id,
     and the glyph it leaves is this sheet's light text-fill on the skin's light
     mobile bar. */
  #header #top-bar .open-menu a {
    background-color: #1c2128 !important;
    border-color: #4a5058 !important;
    color: #eaeaea !important;
    -webkit-text-fill-color: #eaeaea !important;
  }

  #top-bar .open-menu a:hover {
    box-shadow: 0 0 16px 2px rgba(0, 0, 0, .8) !important;
  }

  /* Same fill-property reason; the glyph is the anchor's own "≡" character. */
  #top-bar .mobile-top-bar a {
    color: #eaeaea !important;
    -webkit-text-fill-color: #eaeaea !important;
  }

  /* Themes repaint this input at the same single-id weight, later in the document, so the second id decides it. */
  #header #search-top-box-input,
  #header #search-top-box input.text {
    background-color: #22181a !important;
    color: #e6edf3 !important;
    border-color: #6d4a4a !important;
  }

  #header #search-top-box-input:hover,
  #header #search-top-box-input:focus {
    background-color: #33272a !important;
    border-color: #b98a8a !important;
    color: #fff !important;
  }

  #search-top-box input.empty {
    color: #a08a8a !important;
  }

  #search-top-box-form input[type="submit"] {
    background-color: #5a2f2f !important;
    background-image: linear-gradient(to bottom, #7d4444, #5a2f2f, #33272a) !important;
    border-color: #6d4a4a !important;
    color: #e8d8d8 !important;
  }

  #search-top-box-form input[type="submit"]:hover,
  #search-top-box-form input[type="submit"]:focus {
    background-color: #7d4444 !important;
    background-image: linear-gradient(to bottom, #a06666, #7d4444, #5a2f2f) !important;
    border-color: #b98a8a !important;
    color: #fff !important;
  }

  /* The Basalt family draws the magnifier as a masked `::after` at z-index 1
     under a transparent submit, and the submit is a flex item whose z-index 2
     puts the plate above it. Lifted over the plate; clicks pass through to the
     submit as before. Skins without the pseudo generate no box, so no effect. */
  #search-top-box::after {
    z-index: 3 !important;
    pointer-events: none !important;
  }

  /* SIDE BAR */

  /* Every sidebar SURFACE rule carries the wrapper id: themes repaint these from `#side-bar .side-block` !important, later in the document. `#interwiki` is a separate frame document, uncontested. */
  #container-wrap #side-bar {
    background-color: #14181d !important;
    border-color: #2d333b !important;
  }

  #container-wrap #side-bar .side-block,
  #container-wrap #side-bar #u-side-footer,
  #interwiki .side-block {
    background-color: #1c2128 !important;
    border-color: #7d3030 !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, .55) !important;
  }

  /* The site tints two panels — keep those hues, at dark-surface lightness */
  #container-wrap #side-bar .side-block.media,
  #interwiki .side-block.media {
    background-color: #1e2133 !important;
  }

  #container-wrap #side-bar .side-block.resources,
  #interwiki .side-block.resources {
    background-color: #2a1c1c !important;
  }

  /* Wikidot wraps the heading text in a `p`, and an article theme states that `p`'s colour directly — out of reach of inheritance. */
  #container-wrap #side-bar .heading,
  #container-wrap #side-bar .heading p,
  #interwiki .heading,
  #interwiki .heading p {
    color: #e07b83 !important;
  }

  #container-wrap #side-bar .heading,
  #interwiki .heading {
    border-bottom-color: #7d3030 !important;
  }

  /* Fill cleared so the label returns to the block colour. Image cleared on the wrapper only, so an ornament on the inner `p` survives. */
  #container-wrap #side-bar .heading,
  #interwiki .heading {
    background-color: transparent !important;
    background-image: none !important;
  }

  #container-wrap #side-bar .heading p,
  #interwiki .heading p {
    background-color: transparent !important;
  }

  /* Themes state `#side-bar a` near-black for their white blocks, so the ink comes with the surface: this group and the component rules below carry the wrapper id too. */
  #container-wrap #side-bar a,
  #container-wrap #side-bar a:visited,
  #interwiki a {
    color: var(--scpru-link) !important;
  }

  #container-wrap #side-bar a:hover,
  #interwiki a:hover {
    color: var(--scpru-link-hover) !important;
  }

  #container-wrap #side-bar .menu-item.inactive a,
  #interwiki .menu-item.inactive a {
    color: #7d858e !important;
  }

  #side-bar .menu-item .sub-text,
  #interwiki .menu-item .sub-text {
    color: #8b949e !important;
  }

  /* The row separator carries no colour of its own, so it takes the link/body ink. */
  #side-bar .menu-item,
  #interwiki .menu-item {
    border-color: #2d333b !important;
  }

  /* --- the 2023 sidebar redesign --- */

  #container-wrap #side-bar .new-side-block {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  #container-wrap #side-bar .new-heading {
    color: #e07b83 !important;
    border-top-color: #7d3030 !important;
  }

  #container-wrap #side-bar .new-side-block h6 a {
    color: #c4cdd6 !important;
  }

  /* "Случайная статья" / "Поиск по тегам" */
  #container-wrap #side-bar .random-article-block {
    background: linear-gradient(to top, #1c2128 0%, #1c2128 80%, #262c33 100%) !important;
    border-color: #3a4048 !important;
    box-shadow: 0 2px 3px rgba(0, 0, 0, .5) !important;
  }

  #container-wrap #side-bar .random-article-block .menu-item:first-child {
    border-bottom-color: #3a4048 !important;
  }

  #container-wrap #side-bar .random-article-block > .menu-item a {
    color: #c4cdd6 !important;
  }

  #container-wrap #side-bar .random-article-block .menu-item:first-child:hover,
  #container-wrap #side-bar .random-article-block .menu-item:last-child:hover {
    background: linear-gradient(to top, #7d3030 0%, #7d3030 80%, #a03636 100%) !important;
  }

  #container-wrap #side-bar .random-article-block > .menu-item:hover a {
    color: #fff !important;
  }

  /* Only the white half of the folded gradient is restated, so the hover wipe still reads as a wipe. */
  #container-wrap #side-bar .collapsible-side .collapsible-block-folded {
    background: linear-gradient(to left, #1c2128 50%, var(--new-side-bar-color) 50%) right !important;
    background-size: 200% 100% !important;
  }

  #container-wrap #side-bar .collapsible-side .collapsible-block-folded:hover {
    background-position: left !important;
  }

  #container-wrap #side-bar .collapsible-block-link {
    color: #e07b83 !important;
  }

  #container-wrap #side-bar .collapsible-side .collapsible-block-folded:hover .collapsible-block-link,
  #container-wrap #side-bar .collapsible-side .collapsible-block-unfolded-link a {
    color: #fff !important;
  }

  #side-bar .collapsible-block-unfolded-link {
    border-color: #7d3030 !important;
  }

  /* Mobile slide-out drawer. Below 768px the site fills it dusty rose. */
  @media (max-width: 767px) {
    #container-wrap #side-bar {
      background-color: #0d1117 !important;
    }

    #side-bar:target .close-menu {
      background: rgba(0, 0, 0, .6) !important;
    }
  }

  /* TABLES */

  /* No ink here: td would beat an author box's inherited colour. The cell text inherits; th states its own. */
  table.wiki-content-table td,
  table.wiki-content-table th {
    border-color: #2d333b !important;
  }

  /* An author's white cell border is an invisible spacer on the white page and a drawn grid here; a cell naming its own paper keeps its border. */
  #page-content td[style*="border: 1px solid white"]:not([style*="background"]),
  #page-content td[style*="border:1px solid white"]:not([style*="background"]),
  #page-content td[style*="border: 1px solid #fff"]:not([style*="background"]),
  #page-content td[style*="border:1px solid #fff"]:not([style*="background"]),
  #page-content th[style*="border: 1px solid white"]:not([style*="background"]),
  #page-content th[style*="border:1px solid white"]:not([style*="background"]),
  #page-content th[style*="border: 1px solid #fff"]:not([style*="background"]),
  #page-content th[style*="border:1px solid #fff"]:not([style*="background"]) {
    border-color: transparent !important;
  }

  /* The id form reaches a theme stating the header row from the column id. The bare form covers tables outside the content column. */
  table.wiki-content-table th,
  #main-content table.wiki-content-table th {
    background-color: #22282f !important;
    color: #e6edf3 !important;
  }

  /* Fill and cell ink move together, so a skin that states either one directly keeps it. */
  #page-content table.wiki-content-table {
    --tables-body-bg: 26, 31, 38;
    --tables-body-txt: 196, 205, 214;
  }

  table.page-compare td,
  table.page-compare th,
  table.form.grid td,
  table.form.grid th,
  .gallery-item,
  table.page-history td.optionstd a {
    border-color: #2d333b !important;
  }

  .alternate:nth-child(2n) {
    background-color: rgba(255, 255, 255, .04) !important;
  }

  table.page-files .highlight {
    background-color: #22282f !important;
  }

  /* CODE / TOC / NOTES / QUOTES */

  /* Inline-paper escape as above: these fills are !important, and the ink rebind hands a light box's contents a DARK colour. */
  .code:not([style*="background"]),
  #toc:not([style*="background"]),
  .page-source:not([style*="background"]),
  div.note:not([style*="background"]) {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  div.note-block:not([style*="background"]) {
    border-color: #7d3030 !important;
    background-color: #1a1f26 !important;
  }

  /* Fixed `#ccc`. Sibling separators in `currentColor` are left alone — they track the ink. */
  #toc .title,
  #toc .toc-action-bar,
  #page-content .legend table tr {
    border-bottom-color: #2d333b !important;
  }

  blockquote:not([style*="background"]),
  div.blockquote:not([style*="background"]) {
    background-color: #1a1f26 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6;
  }

  /* Wikidot's own syntax palette */
  .hl-default,
  .hl-code,
  .hl-brackets,
  .hl-identifier,
  .hl-main {
    color: #c9d1d9 !important;
  }

  .hl-comment {
    color: #8b949e !important;
  }

  .hl-quotes,
  .hl-string {
    color: #a5d6ff !important;
  }

  .hl-reserved {
    color: #ff7b72 !important;
  }

  .hl-var {
    color: #79c0ff !important;
  }

  .hl-inlinetags {
    color: #d2a8ff !important;
  }

  .hl-gutter {
    background-color: #22282f !important;
    color: #8b949e !important;
  }

  /* highlight.js, which the site ships in its GitHub LIGHT theme */
  .hljs {
    background-color: #1a1f26 !important;
    color: #c9d1d9 !important;
  }

  .hljs-doctag,
  .hljs-keyword,
  .hljs-meta .hljs-keyword,
  .hljs-template-tag,
  .hljs-template-variable,
  .hljs-type,
  .hljs-variable.language_ {
    color: #ff7b72 !important;
  }

  .hljs-title,
  .hljs-title.class_,
  .hljs-title.class_.inherited__,
  .hljs-title.function_ {
    color: #d2a8ff !important;
  }

  .hljs-attr,
  .hljs-attribute,
  .hljs-literal,
  .hljs-meta,
  .hljs-number,
  .hljs-operator,
  .hljs-variable,
  .hljs-selector-attr,
  .hljs-selector-class,
  .hljs-selector-id {
    color: #79c0ff !important;
  }

  .hljs-regexp,
  .hljs-string,
  .hljs-meta .hljs-string {
    color: #a5d6ff !important;
  }

  .hljs-built_in,
  .hljs-symbol {
    color: #ffa657 !important;
  }

  .hljs-comment,
  .hljs-code,
  .hljs-formula {
    color: #8b949e !important;
  }

  .hljs-name,
  .hljs-quote,
  .hljs-selector-tag,
  .hljs-selector-pseudo {
    color: #7ee787 !important;
  }

  .hljs-subst,
  .hljs-emphasis,
  .hljs-strong {
    color: #c9d1d9 !important;
  }

  .hljs-section {
    color: #79c0ff !important;
  }

  .hljs-bullet {
    color: #e3b341 !important;
  }

  .hljs-addition {
    color: #9be6a8 !important;
    background-color: #16351f !important;
  }

  .hljs-deletion {
    color: #f0a0a0 !important;
    background-color: #3a1a1c !important;
  }

  /* Footnote / bibliography rails */
  .footnotes-footer,
  .bibitems,
  .footnote-footer,
  .footnote .f-content,
  .reference .r-content {
    border-color: #2d333b !important;
    color: #c4cdd6;
  }

  #page-content .footnotes-footer {
    background-color: #1a1f26 !important;
  }

  #page-content .footnotes-footer .title {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* White-on-transparent and only `visibility: hidden` until hovered. */
  #page-content .fncon {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  div.wiki-note,
  .hovertip {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, .6) !important;
  }

  .keycap {
    background-color: #22282f !important;
    border-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  /* ARTICLE FURNITURE */

  .scp-image-block {
    border-color: #3a4048 !important;
    box-shadow: 0 1px 6px rgba(0, 0, 0, .5) !important;
  }

  /* Article themes frame all four sides in their paper colour; the three at zero width cost nothing. */
  .scp-image-block .scp-image-caption {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  /* The wiki-syntax image frames, which carry their caption on a child span. */
  .rimg,
  .limg,
  .cimg {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
    box-shadow: 0 1px 6px rgba(0, 0, 0, .5) !important;
  }

  .rimg span,
  .limg span,
  .cimg span {
    border-top-color: #3a4048 !important;
  }

  /* The `.hover` component's pop-out caption */
  .hover:hover span {
    background-color: #1c2128 !important;
    border-color: #4a5058 !important;
    color: #c4cdd6 !important;
  }

  div.sexy-box {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  div.sexy-box div.image-container img {
    border-color: #3a4048 !important;
  }

  /* Hub pages wrap these in an inline `background-color:#ececec`, so the same inline-paper escape applies. */
  .content-panel:not([style*="background"]) {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, .5) !important;
  }

  .content-panel.standalone:not([style*="background"]) {
    background-color: #1a1f26 !important;
  }

  /* Already `#fcfdfb` in the site's own sheet, so an inline neutral white restates the default rather than naming a paper. Chromatic tints keep the escape above. */
  #page-content .content-panel.standalone[style*="#FFF"],
  #page-content .content-panel.standalone[style*="#fff"],
  #page-content .content-panel.standalone[style*="white"],
  #page-content .content-panel.standalone[style*="#ececec"],
  #page-content .content-panel.standalone[style*="#ECECEC"],
  #page-content .content-panel.standalone[style*="#f5f5f5"],
  #page-content .content-panel.standalone[style*="#F5F5F5"],
  #page-content .content-panel.standalone[style*="#fcfdfb"],
  #page-content .content-panel.standalone[style*="#FCFDFB"] {
    background-color: #1a1f26 !important;
    background-image: none !important;
  }

  /* The body is a background-IMAGE, so a colour alone never reaches it. */
  .content-panel .panel-body {
    background-color: #1c2128 !important;
    background-image: none !important;
    color: #c4cdd6;
  }

  .content-panel .panel-heading {
    color: #f0f0f0;
  }

  /* Index pages state these from the column id, out of reach of the TYPOGRAPHY element rule. Panel-scoped: that surface is ours. */
  #main-content #page-content .content-panel h1 {
    color: var(--scpru-title);
  }

  .content-panel .panel-footer {
    color: #d8d4c8;
  }

  /* Brass GRADIENT, invisible to the inline light-paper detector, with its own brown ink; its two lines are links, so the two-id crimson would land on gold. */
  #main-content #page-content .brass-plaque a,
  #main-content #page-content .brass-plaque a:visited,
  #main-content #page-content .brass-plaque a:hover {
    color: inherit;
  }

  #main-content #page-content .brass-plaque a:hover {
    text-decoration: underline;
  }

  .content-panel .content-toc {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    box-shadow: inset 1px 2px 6px rgba(0, 0, 0, .4) !important;
  }

  /* The join-us call-out on the front page and in the sidebar */
  #u-become-member {
    background-color: #17251d !important;
    border-color: #2c5c36 !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, .5) !important;
  }

  /* The ACS component stretches an anchor over the diamond with `color: transparent` so only the artwork shows; one class, which the two-id article-link rule outweighs. The border takes currentColor. */
  #main-content #page-content .danger-diamond a,
  #main-content #page-content .danger-diamond a:visited,
  #main-content #page-content .danger-diamond a:hover {
    color: transparent !important;
    border-color: transparent !important;
  }

  /* Already a dark maroon; only its cream rule is pitched down. */
  .heritage-rating-module {
    border-color: #8a7a3a !important;
  }

  div#u-adult-warning {
    background-color: #1c2128 !important;
    border-color: #4a5058 !important;
    color: #c4cdd6 !important;
  }

  div#u-adult-warning > div#u-adult-header {
    color: #e05f6b !important;
  }

  div#u-adult-warning .choice a {
    color: #e8626e !important;
  }

  div#u-adult-warning .choice a:hover {
    color: #ff8f97 !important;
  }

  /* Both banners stay loud on purpose; only the white frame and the ink they inherit are restated. */
  .archieved-message {
    border-color: #6d5a2a !important;
    box-shadow: 0 0 0 2px #d4b820 !important;
    background: #d4b820 !important;
    color: #140f0c !important;
  }

  .broken-message {
    border-color: #7a4a20 !important;
    box-shadow: 0 0 0 2px #d67a2a !important;
    background: #d67a2a !important;
    color: #140f0c !important;
  }

  .archieved-message a,
  .broken-message a {
    color: #7a1d24 !important;
  }

  .scpnet-progress-bar {
    background-color: #22282f !important;
  }

  .scpnet-progress-bar__tick {
    background-color: #6b737c !important;
  }

  .scpru-copyright-notice,
  .scpru-copyright-notice a,
  .lil-text {
    color: #8b949e !important;
  }

  .more-author-articles {
    border-top-color: #2d333b !important;
  }

  .ny2017-link a {
    background-color: #1a5c2a !important;
    color: #fff !important;
  }

  /* Wikidot tag pill */
  .tags {
    background-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  .tags::before {
    border-right-color: #3a4048 !important;
  }

  .tags::after {
    background-color: #c4cdd6 !important;
    box-shadow: -1px -1px 2px #14181d !important;
  }

  #main-content .page-tags,
  #main-content .page-tags span {
    border-top-color: #2d333b !important;
  }

  #main-content .page-tags strong {
    color: #8b949e !important;
  }

  /* Furniture, not author prose: link colour pinned against themes that darken it, chip fill cleared. */
  #main-content .page-tags a,
  #page-content .footer-wikiwalk-nav a {
    background-color: transparent !important;
    color: #e8626e !important;
  }

  #main-content .page-tags a::before {
    border-color: transparent !important;
  }

  #main-content .page-tags a:hover,
  #page-content .footer-wikiwalk-nav a:hover {
    color: #ff8f97 !important;
  }

  /* Inline per-tag colours, the whole range below AA here; font size carries the same frequency signal. */
  #page-content a.tag {
    color: #e8626e !important;
  }

  #page-content a.tag:hover {
    color: #ff8f97 !important;
  }

  #page-content a.tag.active {
