  }

  /* STAR RATING MODULE
     The RU branch's five-star control draws its stars as Font Awesome GLYPHS,
     so both star rows are text colours. */

  .w-stars-rate-module {
    color: #c4cdd6 !important;
  }

  .w-stars-rate-module .w-stars-rate-rating,
  .w-stars-rate-module .w-stars-rate-votes {
    background-color: #2d333b !important;
  }

  /* The site's own #4e6b6b is unreadable on a dark plate; same hue, lifted. */
  .w-stars-rate-module .w-stars-rate-number,
  .w-stars-rate-module .w-stars-rate-votes {
    color: #6fb6b6 !important;
  }

  .w-stars-rate-module .w-stars-rate-control {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    box-shadow: 0 0 4px rgba(0, 0, 0, .5) !important;
  }

  /* Deliberately low-contrast: a legible "off" star would read as a lit one and invert the rating. */
  .w-stars-rate-module .w-stars-rate-stars-wrapper::before {
