  }

  /* Wikidot's ± widget, still used by the forum and by older pages */
  .page-rate-widget-box {
    box-shadow: 1px 1px 4px rgba(0, 0, 0, .6) !important;
  }

  div.page-rate-widget-box .rate-points {
