  /* AUTHOR-WRITTEN INLINE COLOURS
     ##blue|text## emits a literal inline `color:` whose dark end is unreadable
     here. Every selector is guarded against `background-color: red`, which
     contains the substring `color:red`: unguarded, a span that named only a
     FILL has its ink repainted the same hue and vanishes. */

  #page-content [style*="color:black"]:not([style*="background"]),
  #page-content [style*="color: black"]:not([style*="background"]),
  #page-content [style*="color:#000"]:not([style*="background"]),
  #page-content [style*="color: #000"]:not([style*="background"]) {
    color: var(--scpru-lift-black) !important;
  }

  /* Keyword and its own hex are the same colour: carrying one spelling and not the other leaves the other on the page floor. */
  #page-content [style*="color:blue"]:not([style*="background"]),
  #page-content [style*="color: blue"]:not([style*="background"]),
  #page-content [style*="color:  blue"]:not([style*="background"]),
  #page-content [style*="color:navy"]:not([style*="background"]),
  #page-content [style*="color: navy"]:not([style*="background"]),
  #page-content [style*="color:#0000ff"]:not([style*="background"]),
  #page-content [style*="color: #0000ff"]:not([style*="background"]),
  #page-content [style*="color:#282467"]:not([style*="background"]),
  #page-content [style*="color: #282467"]:not([style*="background"]),
  #page-content [style*="color:#04b"]:not([style*="background"]),
  #page-content [style*="color: #04b"]:not([style*="background"]),
  #page-content [style*="color:steelblue"]:not([style*="background"]),
