  #page-content [style*="color:SteelBlue"]:not([style*="background"]),
  #page-content [style*="color: SteelBlue"]:not([style*="background"]),
  #page-content [style*="color:#4682b4"]:not([style*="background"]),
  #page-content [style*="color: #4682b4"]:not([style*="background"]),
  #page-content [style*="color:royalblue"]:not([style*="background"]),
  #page-content [style*="color: royalblue"]:not([style*="background"]) {
    color: var(--scpru-lift-blue) !important;
  }

  #page-content [style*="color:green"]:not([style*="background"]),
  #page-content [style*="color: green"]:not([style*="background"]),
  #page-content [style*="color:#008000"]:not([style*="background"]),
  #page-content [style*="color: #008000"]:not([style*="background"]),
  #page-content [style*="color:#057800"]:not([style*="background"]),
  #page-content [style*="color: #057800"]:not([style*="background"]),
  #page-content [style*="color:#060"]:not([style*="background"]),
  #page-content [style*="color: #060"]:not([style*="background"]),
  #page-content [style*="color:#0a460a"]:not([style*="background"]),
  #page-content [style*="color: #0a460a"]:not([style*="background"]) {
    color: var(--scpru-lift-green) !important;
  }

  /* The attribute match is literal, so a second space after the colon is a separate spelling and needs an entry of its own. */
  #page-content [style*="color:purple"]:not([style*="background"]),
  #page-content [style*="color: purple"]:not([style*="background"]),
  #page-content [style*="color:  purple"]:not([style*="background"]),
  #page-content [style*="color:indigo"]:not([style*="background"]),
  #page-content [style*="color: indigo"]:not([style*="background"]),
  #page-content [style*="color:#800080"]:not([style*="background"]),
  #page-content [style*="color: #800080"]:not([style*="background"]),
  #page-content [style*="color:#606"]:not([style*="background"]),
  #page-content [style*="color: #606"]:not([style*="background"]) {
    color: var(--scpru-lift-purple) !important;
  }

  #page-content [style*="color:maroon"]:not([style*="background"]),
  #page-content [style*="color: maroon"]:not([style*="background"]),
  #page-content [style*="color:darkred"]:not([style*="background"]),
  #page-content [style*="color: darkred"]:not([style*="background"]),
  #page-content [style*="color:#800000"]:not([style*="background"]),
  #page-content [style*="color: #800000"]:not([style*="background"]),
  #page-content [style*="color:#990000"]:not([style*="background"]),
  #page-content [style*="color: #990000"]:not([style*="background"]),
  #page-content [style*="color:#990011"]:not([style*="background"]),
  #page-content [style*="color: #990011"]:not([style*="background"]),
  #page-content [style*="color:#900"]:not([style*="background"]),
  #page-content [style*="color: #900"]:not([style*="background"]),
  #page-content [style*="color:#a00"]:not([style*="background"]),
  #page-content [style*="color: #a00"]:not([style*="background"]),
  #page-content [style*="color:firebrick"]:not([style*="background"]),
  #page-content [style*="color: firebrick"]:not([style*="background"]),
  #page-content [style*="color:#b22222"]:not([style*="background"]),
  #page-content [style*="color: #b22222"]:not([style*="background"]),
  #page-content [style*="color:#ce005c"]:not([style*="background"]),
  #page-content [style*="color: #ce005c"]:not([style*="background"]),
  #page-content [style*="color:#b04164"]:not([style*="background"]),
  #page-content [style*="color: #b04164"]:not([style*="background"]) {
    color: var(--scpru-lift-maroon) !important;
  }

  /* Pure red lands at 4.46:1 — a hair under AA. Softened just enough to pass
     while staying unmistakably the same red. */
  #page-content [style*="color:red"]:not([style*="background"]),
  #page-content [style*="color: red"]:not([style*="background"]),
  #page-content [style*="color:#ff0000"]:not([style*="background"]),
  #page-content [style*="color: #ff0000"]:not([style*="background"]) {
    color: var(--scpru-lift-red) !important;
  }

  #page-content [style*="color:brown"]:not([style*="background"]),
  #page-content [style*="color: brown"]:not([style*="background"]),
  #page-content [style*="color:#a52a2a"]:not([style*="background"]),
  #page-content [style*="color: #a52a2a"]:not([style*="background"]),
  #page-content [style*="color:#743"]:not([style*="background"]),
  #page-content [style*="color: #743"]:not([style*="background"]),
  #page-content [style*="color:sienna"]:not([style*="background"]),
  #page-content [style*="color: sienna"]:not([style*="background"]),
  #page-content [style*="color:#a0522d"]:not([style*="background"]),
  #page-content [style*="color: #a0522d"]:not([style*="background"]) {
    color: var(--scpru-lift-brown) !important;
  }

  #page-content [style*="color:teal"]:not([style*="background"]),
  #page-content [style*="color: teal"]:not([style*="background"]),
  #page-content [style*="color:#008080"]:not([style*="background"]),
  #page-content [style*="color: #008080"]:not([style*="background"]) {
    color: var(--scpru-lift-teal) !important;
  }

  /* The branch's own title and link crimsons, which authors paste into inline `color:` on fake page titles and section heads. */
  #page-content [style*="color:#901"]:not([style*="background"]),
  #page-content [style*="color: #901"]:not([style*="background"]),
  #page-content [style*="color:#b01"]:not([style*="background"]),
  #page-content [style*="color: #b01"]:not([style*="background"]),
  #page-content [style*="color:#a01"]:not([style*="background"]),
  #page-content [style*="color: #a01"]:not([style*="background"]),
  #page-content [style*="color:#700"]:not([style*="background"]),
  #page-content [style*="color: #700"]:not([style*="background"]),
  #page-content [style*="color:#600"]:not([style*="background"]),
  #page-content [style*="color: #600"]:not([style*="background"]) {
    color: var(--scpru-lift-maroon) !important;
  }

  /* FOOTER / LICENSE / NAVI */

  #container-wrap #footer {
    background-color: #0d1117 !important;
    color: #8b949e !important;
    border-top: 1px solid #262c33;
  }

  /* The engine credit bar is dark on the live site and its links are white there. */
  #footer a {
    color: #c4cdd6 !important;
  }

  /* Light band on the live site, its one link the branch crimson; body ink there is the sentence's own tone and has no underline to fall back on. */
  #license-area a,
  .license-area a {
    color: var(--scpru-link) !important;
  }

  #footer a:hover,
  #license-area a:hover,
  .license-area a:hover {
    color: #ff8f97 !important;
  }

  #container-wrap #license-area,
  .license-area {
    background-color: #0d1117 !important;
    color: #8b949e !important;
  }

  /* Unstated in the site's own sheets, so a theme that states it holds it at its light-column near-black. The value is the body ink, so the default skin is unchanged. */
  #page-info,
  #page-info .odate {
    color: #c4cdd6 !important;
  }

  #navi-bar {
    background-color: #0d1117 !important;
    border-bottom-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  #navi-bar a,
  #navi-bar .action-buttons,
  #navi-bar .action-buttons a,
  #navi-bar .join,
  #navi-bar .random-site {
    color: #8ab4d8 !important;
  }

  #navi-bar .new-site input.empty {
    color: #8b949e !important;
  }

  #footer-bar {
    border-top-color: #262c33 !important;
  }

  /* Wikidot's own house ad slot, which punches a white hole in the page */
  #house-ad-1 {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  #house-ad-1 .close {
    background-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  .self-ads {
    border-color: #2d333b !important;
  }

  /* SCROLLBAR */

  ::-webkit-scrollbar {
    border-color: rgba(255, 255, 255, .08) !important;
  }

  ::-webkit-scrollbar-track {
    background-color: #0d1117 !important;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #3a4048 !important;
  }

  ::-webkit-scrollbar-thumb:hover {
    background-color: #4a5058 !important;
  }

  /* INTERWIKI FRAME (other-languages box) */

  #interwiki body,
  body#interwiki {
    background-color: transparent !important;
  }

  iframe.scpnet-interwiki-frame {
    background-color: #14181d !important;
  }

  #interwiki .menu-item a {
    color: #e8626e !important;
  }
}

@-moz-document url-prefix("https://scpfoundation.net/wiki-syntax-guide") {
#page-content code,
  #page-content .code,
  #page-content .code pre {
    background-color: #1a1f26 !important;
    color: var(--scpru-lift-green) !important;
  }

  /* Same page <style>: white paper, ink inherited from #page-content. */
  #page-content dl,
  #page-content dl > dt,
  #page-content dl > dd {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
}

@-moz-document url-prefix("https://scpfoundation.net/series-archive") {
#page-content .series-block:not([style*="background"]) {
    background-color: #1c2128 !important;
  }

  /* The footer strip is a chip painted on the link itself (grey, or the block's accent), so knocked-out white is the only ink clearing AA on every accent. */
  #main-content #page-content .series-block .tag-lead a {
    color: #ffffff !important;
  }

  /* The page states the section rule from `:where(#page-content) h2` — zero specificity. Scoped, so an article's own h2 rule, drawn in `currentColor`, is left alone. */
  #page-content h2 {
    border-bottom-color: #2d333b !important;
  }

  #page-content .series-block .blurb {
    border-top-color: #3a4048 !important;
  }
}

@-moz-document url-prefix("https://scpfoundation.net/canon-hub"), url-prefix("https://scpfoundation.net/foundation-tales") {
#page-content .canon-block:not([style*="background"]),
  #page-content .tale-block:not([style*="background"]) {
    background-color: #1c2128 !important;
  }

  /* A pill the same <style> paints pale green, which the crimson link colour sits on at 2.7:1. */
  #page-content a.collapsible-block-link {
    background-color: #1a1f26 !important;
  }
}

@-moz-document url-prefix("https://scpfoundation.net/components-hub"), url-prefix("https://scpfoundation.net/themes-hub") {
div.modal,
  #page-content .page-block {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* The hub's warning variant is a red wash and frame over the modal paper; the wash stays a tint of the branch crimson so it still reads as a warning and not a second neutral plate. */
  div.modal.themes-warning {
    background-color: #2a1618 !important;
    border-color: #8a2f2f !important;
  }

  div.modal h1,
  div.modal h2,
  div.modal h3,
  div.modal h4,
  div.modal h5 {
    color: var(--scpru-heading) !important;
  }

  #page-content .page-block .title {
    color: var(--scpru-title) !important;
  }

  #page-content .page-block .date {
    color: #8b949e !important;
  }

  #page-content .pager {
    background-color: rgba(28, 33, 40, 0.85) !important;
  }

  /* #333 marks the active page size. Stated !important from a sheet loaded after ours, so both ids and !important are needed. */
  #main-content #page-content a[href="/components-hub"],
  #main-content #page-content a[href="/themes-hub"] {
    color: #8b949e !important;
  }
}

